<?php\n\ndeclare(strict_types=1);\n\nnamespace App\\Service\\Notification;\n\nuse App\\Entity\\NotificationDelivery;\nuse App\\Entity\\NotificationEvent;\nuse App\\Entity\\User;\nuse App\\Repository\\NotificationDeliveryRepository;\nuse App\\Repository\\NotificationPreferenceRepository;\nuse App\\Service\\EmailSender;\nuse Doctrine\\ORM\\EntityManagerInterface;\nuse Psr\\Log\\LoggerInterface;\nuse Symfony\\Component\\Routing\\Generator\\UrlGeneratorInterface;\nuse Twig\\Environment;\n\nfinal class EmailNotificationService\n{\n    public function __construct(\n        private readonly EntityManagerInterface $em,\n        private readonly NotificationPreferenceRepository $preferences,\n        private readonly NotificationDeliveryRepository $deliveries,\n        private readonly EmailSender $emailSender,\n        private readonly Environment $twig,\n        private readonly UrlGeneratorInterface $urlGenerator,\n        private readonly LoggerInterface $logger,\n    ) {\n    }\n\n    public function dispatch(\n        string $type,\n        string $title,\n        string $body,\n        ?string $link = null,\n        ?string $entityType = null,\n        ?int $entityId = null,\n        ?User $createdBy = null,\n    ): NotificationEvent {\n        $event = new NotificationEvent($type, $title, $body, $link, $entityType, $entityId, $createdBy);\n        $this->em->persist($event);\n\n        foreach ($this->preferences->findEmailSubscribers($type) as $preference) {\n            $this->createDelivery($event, $preference->getUser(), $createdBy);\n        }\n\n        $this->em->flush();\n\n        return $event;\n    }\n\n    /** @param list<User> $recipients */\n    public function dispatchToUsers(\n        string $type,\n        string $title,\n        string $body,\n        array $recipients,\n        ?string $link = null,\n        ?string $entityType = null,\n        ?int $entityId = null,\n        ?User $createdBy = null,\n    ): ?NotificationEvent {\n        $recipients = array_values(array_filter($recipients, static fn(mixed $user): bool => $user instanceof User));\n\n        if ($recipients === []) {\n            return null;\n        }\n\n        $event = new NotificationEvent($type, $title, $body, $link, $entityType, $entityId, $createdBy);\n        $this->em->persist($event);\n\n        foreach ($recipients as $user) {\n            $this->createDelivery($event, $user, $createdBy);\n        }\n\n        $this->em->flush();\n\n        return $event;\n    }\n\n    private function createDelivery(NotificationEvent $event, User $user, ?User $exclude): void\n    {\n        if ($exclude !== null && $user->getId() === $exclude->getId()) {\n            return;\n        }\n\n        $preference = $this->preferences->findForUser($user);\n\n        if (!$preference->accepts($event->getType())) {\n            return;\n        }\n\n        $email = trim((string) $user->getEmail());\n\n        if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {\n            return;\n        }\n\n        if ($this->deliveries->findOneBy(['event' => $event, 'user' => $user]) !== null) {\n            return;\n        }\n\n        $this->em->persist(new NotificationDelivery($event, $user, $email));\n    }\n\n    /** @return array{sent: int, failed: int, skipped: int} */\n    public function sendPending(int $limit = 100): array\n    {\n        $result = ['sent' => 0, 'failed' => 0, 'skipped' => 0];\n\n        foreach ($this->deliveries->findPending($limit) as $delivery) {\n            if (!$delivery->canRetry()) {\n                $result['skipped']++;\n                continue;\n            }\n\n            $event = $delivery->getEvent();\n            $link = $event->getLink();\n\n            if ($link !== null && !str_starts_with($link, 'http://') && !str_starts_with($link, 'https://')) {\n                $link = $this->urlGenerator->generate('public_radar_index', [], UrlGeneratorInterface::ABSOLUTE_URL);\n            }\n\n            try {\n                $html = $this->twig->render('emails/notification.html.twig', [\n                    'event' => $event,\n                    'link' => $link,\n                ]);\n\n                $this->emailSender->send(\n                    $delivery->getEmail(),\n                    null,\n                    '[ToolboxWaze] ' . $event->getTitle(),\n                    $html,\n                );\n\n                $delivery->markSent();\n                $result['sent']++;\n            } catch (\\Throwable $exception) {\n                $delivery->markFailed($exception->getMessage());\n                $result['failed']++;\n                $this->logger->warning('Falha ao enviar notificação por e-mail.', [\n                    'delivery' => $delivery->getId(),\n                    'event' => $event->getId(),\n                    'error' => $exception->getMessage(),\n                ]);\n            }\n\n            $this->em->flush();\n        }\n\n        return $result;\n    }\n}\n